const std = @import("std");
const bitmap = @import("../bitmap.zig");
const buffer = @import("../buffer.zig");
const array_utils = @import("array_utils.zig");
const array_ref = @import("array_ref.zig");
const builder_state = @import("builder_state.zig");
const datatype = @import("../datatype.zig");
const array_data = @import("array_data.zig");

// Generic fixed-width primitive array views/builders.

const SharedBuffer = buffer.SharedBuffer;
const OwnedBuffer = buffer.OwnedBuffer;
const DataType = datatype.DataType;
const ArrayData = array_data.ArrayData;
const AccessorError = array_data.AccessorError;
const ArrayRef = array_ref.ArrayRef;
const BuilderState = builder_state.BuilderState;

/// Generic array view for fixed-width primitive types.
pub fn PrimitiveArray(comptime T: type) type {
    return struct {
        data: *const ArrayData,

        const Self = @This();

        pub const Error = AccessorError;

        /// Return the logical length.
        pub fn len(self: Self) usize {
            return self.data.length;
        }

        /// Check whether the element at index is null.
        pub fn isNull(self: Self, i: usize) bool {
            return self.data.isNull(i);
        }

        pub fn values(self: Self) Error![]const T {
            // Primitive arrays require [validity] and [values] buffers.
            const raw = try self.data.typedBufferAt(1, T);
            const start = self.data.offset;
            const end = try self.data.logicalEnd();
            if (end > raw.len) return error.BufferTooSmall;
            return raw[start..end];
        }

        /// Return the logical value view at the requested index.
        pub fn value(self: Self, i: usize) Error!T {
            if (i >= self.data.length) return error.IndexOutOfBounds;
            return (try self.values())[i];
        }
    };
}

/// Generic builder for fixed-width primitive arrays.
/// The caller must specify the data type and handle validity bits as needed.
pub fn PrimitiveBuilder(comptime T: type, comptime dtype: DataType) type {
    return struct {
        allocator: std.mem.Allocator,
        values: OwnedBuffer,
        validity: ?OwnedBuffer = null,
        buffers: [2]SharedBuffer = undefined,
        len: usize = 0,
        null_count: usize = 0,
        state: BuilderState = .ready,

        const Self = @This();

        const Error = error{ AlreadyFinished, NotFinished };

        const TYPE: DataType = dtype;

        /// Initialize and return a new instance.
        pub fn init(allocator: std.mem.Allocator, capacity: usize) !Self {
            return .{
                .allocator = allocator,
                .values = try OwnedBuffer.init(allocator, capacity * @sizeOf(T)),
            };
        }

        /// Release resources owned by this instance.
        pub fn deinit(self: *Self) void {
            self.values.deinit();
            if (self.validity) |*valid| valid.deinit();
        }

        /// Reset state while retaining reusable capacity when possible.
        pub fn reset(self: *Self) Error!void {
            if (self.state != .finished) return Error.NotFinished;
            self.len = 0;
            self.null_count = 0;
            self.state = .ready;
        }

        /// Clear state and release reusable buffers when required.
        pub fn clear(self: *Self) Error!void {
            if (self.state != .finished) return Error.NotFinished;
            self.values.deinit();
            if (self.validity) |*valid| valid.deinit();
            self.validity = null;
            self.len = 0;
            self.null_count = 0;
            self.state = .ready;
        }

        fn ensureValuesCapacity(self: *Self, new_len: usize) !void {
            const capacity = self.values.len() / @sizeOf(T);
            if (new_len <= capacity) return;
            try self.values.resize(new_len * @sizeOf(T));
        }

        /// Append one logical value into the builder.
        pub fn append(self: *Self, value: T) !void {
            if (self.state == .finished) return Error.AlreadyFinished;
            const next_len = self.len + 1;
            try self.ensureValuesCapacity(next_len);
            const slice = std.mem.bytesAsSlice(T, self.values.data);
            slice[self.len] = value;
            try array_utils.setValidBit(&self.validity, self.len);
            self.len = next_len;
        }

        /// Ensure capacity for `additional` more values without further reallocation.
        pub fn reserve(self: *Self, additional: usize) !void {
            try self.ensureValuesCapacity(self.len + additional);
            if (self.validity) |*valid| try array_utils.ensureBitmapCapacity(valid, self.len + additional);
        }

        /// Append non-null values in bulk (one memcpy when no validity bitmap exists yet).
        pub fn appendSlice(self: *Self, items: []const T) !void {
            if (self.state == .finished) return Error.AlreadyFinished;
            try self.reserve(items.len);
            const slice = std.mem.bytesAsSlice(T, self.values.data);
            @memcpy(slice[self.len..][0..items.len], items);
            if (self.validity) |*valid| {
                for (self.len..self.len + items.len) |i| bitmap.setBit(valid.data, i);
            }
            self.len += items.len;
        }

        /// Append a null entry into the builder.
        pub fn appendNull(self: *Self) !void {
            if (self.state == .finished) return Error.AlreadyFinished;
            const next_len = self.len + 1;
            try self.ensureValuesCapacity(next_len);
            try array_utils.ensureValidityForNull(self.allocator, &self.validity, &self.null_count, next_len);
            self.len = next_len;
        }

        /// Finalize builder state and return an immutable array reference.
        pub fn finish(self: *Self) !ArrayRef {
            if (self.state == .finished) return Error.AlreadyFinished;
            const validity_buf = try array_utils.takeValidity(&self.validity, self.len);
            self.buffers[0] = validity_buf;
            self.buffers[1] = try self.values.toShared(self.len * @sizeOf(T));

            const data = ArrayData{
                .data_type = TYPE,
                .length = self.len,
                .null_count = self.null_count,
                .buffers = self.buffers[0..],
            };

            self.state = .finished;
            return ArrayRef.fromOwnedInlineBuffers(self.allocator, data);
        }

        /// Finalize output and then reset builder state for reuse.
        pub fn finishReset(self: *Self) !ArrayRef {
            const finished_ref = try self.finish();
            try self.reset();
            return finished_ref;
        }
    };
}

test "primitive builder appends values and nulls" {
    var builder = try PrimitiveBuilder(i32, DataType{ .int32 = {} }).init(std.testing.allocator, 2);
    defer builder.deinit();

    try builder.append(10);
    try builder.appendNull();
    try builder.append(30);

    var array_handle = try builder.finish();
    defer array_handle.release();
    const built = PrimitiveArray(i32){ .data = array_handle.data() };
    try std.testing.expectEqual(@as(usize, 3), built.len());
    try std.testing.expect(built.isNull(1));
    try std.testing.expectEqual(@as(i32, 30), try built.value(2));
    try std.testing.expectError(error.IndexOutOfBounds, built.value(3));
}

test "primitive builder appendSlice matches per-element append" {
    var builder = try PrimitiveBuilder(i32, DataType{ .int32 = {} }).init(std.testing.allocator, 0);
    defer builder.deinit();

    try builder.appendSlice(&.{ 1, 2 });
    try builder.appendNull();
    try builder.appendSlice(&.{ 4, 5, 6 });

    var array_handle = try builder.finish();
    defer array_handle.release();
    const built = PrimitiveArray(i32){ .data = array_handle.data() };
    try std.testing.expectEqual(@as(usize, 6), built.len());
    try std.testing.expect(built.isNull(2));
    try std.testing.expect(!built.isNull(3) and !built.isNull(5));
    try std.testing.expectEqual(@as(i32, 6), try built.value(5));
    try std.testing.expectEqual(@as(usize, 1), array_handle.data().null_count.?);
}

test "primitive array values returns error for missing value buffer" {
    const buffers = [_]SharedBuffer{SharedBuffer.empty};
    const data = ArrayData{
        .data_type = DataType{ .int32 = {} },
        .length = 1,
        .null_count = 0,
        .buffers = &buffers,
    };
    const view = PrimitiveArray(i32){ .data = &data };
    try std.testing.expectError(error.InvalidBufferCount, view.values());
}
const std = @import("std");
const bitmap = @import("../bitmap.zig");
const buffer = @import("../buffer.zig");

// Shared helper routines used by multiple array builders.

pub const OwnedBuffer = buffer.OwnedBuffer;

pub fn initValidityAllValid(allocator: std.mem.Allocator, bit_len: usize) !OwnedBuffer {
    const used_bytes = bitmap.byteLength(bit_len);
    var buf = try OwnedBuffer.init(allocator, used_bytes);
    if (used_bytes > 0) {
        @memset(buf.data[0..used_bytes], 0xFF);
        const remainder = bit_len & 7;
        if (remainder != 0) {
            const keep_mask = (@as(u8, 1) << @as(u3, @intCast(remainder))) - 1;
            buf.data[used_bytes - 1] &= keep_mask;
        }
    }
    return buf;
}

pub fn ensureBitmapCapacity(buf: *OwnedBuffer, bit_len: usize) !void {
    const needed = bitmap.byteLength(bit_len);
    if (needed <= buf.len()) return;
    try buf.resize(needed);
}

/// Ensure validity storage exists, mark the new appended slot as null, and bump null count.
pub fn ensureValidityForNull(
    allocator: std.mem.Allocator,
    validity: *?OwnedBuffer,
    null_count: *usize,
    new_len: usize,
) !void {
    std.debug.assert(new_len > 0);
    if (validity.* == null) {
        var buf = try initValidityAllValid(allocator, new_len);
        bitmap.clearBit(buf.data[0..bitmap.byteLength(new_len)], new_len - 1);
        validity.* = buf;
        null_count.* += 1;
        return;
    }
    var buf = &validity.*.?;
    try ensureBitmapCapacity(buf, new_len);
    bitmap.clearBit(buf.data[0..bitmap.byteLength(new_len)], new_len - 1);
    null_count.* += 1;
}

/// Hand the validity bitmap to a SharedBuffer and drop it from the builder, so the next
/// batch only allocates validity if it actually appends a null.
pub fn takeValidity(validity: *?OwnedBuffer, len: usize) !buffer.SharedBuffer {
    const buf = if (validity.*) |*b| b else return buffer.SharedBuffer.empty;
    const shared = try buf.toShared(bitmap.byteLength(len));
    validity.* = null;
    return shared;
}

/// Mark an existing appended slot as valid if a validity bitmap has been allocated.
pub fn setValidBit(validity: *?OwnedBuffer, index: usize) !void {
    if (validity.* == null) return;
    var buf = &validity.*.?;
    try ensureBitmapCapacity(buf, index + 1);
    bitmap.setBit(buf.data[0..bitmap.byteLength(index + 1)], index);
}

test "initValidityAllValid marks bits and clears padding" {
    const allocator = std.testing.allocator;

    var buf = try initValidityAllValid(allocator, 10);
    defer buf.deinit();

    try std.testing.expectEqual(@as(usize, 10), bitmap.countSetBit(buf.data, 10));
    var i: usize = 0;
    while (i < 10) : (i += 1) {
        try std.testing.expect(bitmap.bitIsSet(buf.data, i));
    }

    const bit_cap = bitmap.byteLength(10) * 8;
    i = 10;
    while (i < bit_cap) : (i += 1) {
        try std.testing.expect(!bitmap.bitIsSet(buf.data, i));
    }
}

test "initValidityAllValid handles zero length" {
    const allocator = std.testing.allocator;

    var buf = try initValidityAllValid(allocator, 0);
    defer buf.deinit();

    try std.testing.expectEqual(@as(usize, 0), bitmap.countSetBit(buf.data, 0));
}

test "ensureBitmapCapacity grows buffer" {
    const allocator = std.testing.allocator;

    var buf = try OwnedBuffer.init(allocator, 1);
    defer buf.deinit();

    const before = buf.len();
    try ensureBitmapCapacity(&buf, (before + 1) * 8);
    try std.testing.expect(buf.len() > before);
}

const std = @import("std");
const zarrow = @import("zarrow");
const csv_meta = @import("csv_meta.zig");

const Mode = enum { default, smoke, full, matrix, matrix_no_header, ci, ci_no_header };

const BenchConfig = struct {
    rows: usize,
    iterations: usize,
};

fn parseMode(init: std.process.Init, allocator: std.mem.Allocator) !Mode {
    var args = try init.minimal.args.iterateAllocator(allocator);
    defer args.deinit();

    _ = args.next();
    const mode_str = args.next() orelse return .default;

    if (std.mem.eql(u8, mode_str, "smoke")) return .smoke;
    if (std.mem.eql(u8, mode_str, "full")) return .full;
    if (std.mem.eql(u8, mode_str, "matrix")) return .matrix;
    if (std.mem.eql(u8, mode_str, "matrix-no-header")) return .matrix_no_header;
    if (std.mem.eql(u8, mode_str, "ci")) return .ci;
    if (std.mem.eql(u8, mode_str, "ci-no-header")) return .ci_no_header;
    return .default;
}

fn printCsvHeader() void {
    std.debug.print("benchmark,rows,iterations,elapsed_ns,rows_per_sec,ns_per_row,checksum,git_sha,timestamp\n", .{});
}

fn runBenchmark(io: std.Io, allocator: std.mem.Allocator, cfg: BenchConfig, emit_csv: bool, meta: csv_meta.CsvMeta) !void {
    var builder = try zarrow.Int32Builder.init(allocator, cfg.rows);
    defer builder.deinit();

    var checksum: i64 = 0;
    const timer_start = std.Io.Timestamp.now(io, .awake);

    var iter: usize = 0;
    while (iter < cfg.iterations) : (iter += 1) {
        var i: usize = 0;
        while (i < cfg.rows) : (i += 1) {
            const v: i32 = @intCast((i + iter) % 1024);
            try builder.append(v);
            checksum += v;
        }

        var arr = try builder.finishReset();
        defer arr.release();
    }

    const elapsed_ns: u64 = @intCast(timer_start.untilNow(io, .awake).toNanoseconds());
    const total_rows = cfg.rows * cfg.iterations;
    const rows_per_sec = (@as(f64, @floatFromInt(total_rows)) * 1_000_000_000.0) / @as(f64, @floatFromInt(elapsed_ns));
    const ns_per_row = @as(f64, @floatFromInt(elapsed_ns)) / @as(f64, @floatFromInt(total_rows));

    if (emit_csv) {
        std.debug.print("primitive_builder,{d},{d},{d},{d:.2},{d:.2},{d},{s},{d}\n", .{
            cfg.rows,
            cfg.iterations,
            elapsed_ns,
            rows_per_sec,
            ns_per_row,
            checksum,
            meta.git_sha,
            meta.timestamp,
        });
        return;
    }

    std.debug.print("benchmark=primitive_builder rows={d} iterations={d} elapsed_ns={d} rows_per_sec={d:.2} ns_per_row={d:.2} checksum={d}\n", .{
        cfg.rows,
        cfg.iterations,
        elapsed_ns,
        rows_per_sec,
        ns_per_row,
        checksum,
    });
}

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const allocator = std.heap.page_allocator;
    const mode = try parseMode(init, allocator);
    const meta = try csv_meta.resolve(init, allocator);
    defer meta.deinit(allocator);

    switch (mode) {
        .smoke => try runBenchmark(io, allocator, .{ .rows = 10_000, .iterations = 20 }, false, meta),
        .full => try runBenchmark(io, allocator, .{ .rows = 500_000, .iterations = 120 }, false, meta),
        .matrix => {
            printCsvHeader();
            try runBenchmark(io, allocator, .{ .rows = 1_000, .iterations = 500 }, true, meta);
            try runBenchmark(io, allocator, .{ .rows = 10_000, .iterations = 120 }, true, meta);
            try runBenchmark(io, allocator, .{ .rows = 100_000, .iterations = 20 }, true, meta);
        },
        .matrix_no_header => {
            try runBenchmark(io, allocator, .{ .rows = 1_000, .iterations = 500 }, true, meta);
            try runBenchmark(io, allocator, .{ .rows = 10_000, .iterations = 120 }, true, meta);
            try runBenchmark(io, allocator, .{ .rows = 100_000, .iterations = 20 }, true, meta);
        },
        .ci => {
            printCsvHeader();
            try runBenchmark(io, allocator, .{ .rows = 1_000, .iterations = 80 }, true, meta);
            try runBenchmark(io, allocator, .{ .rows = 10_000, .iterations = 20 }, true, meta);
            try runBenchmark(io, allocator, .{ .rows = 100_000, .iterations = 4 }, true, meta);
        },
        .ci_no_header => {
            try runBenchmark(io, allocator, .{ .rows = 1_000, .iterations = 80 }, true, meta);
            try runBenchmark(io, allocator, .{ .rows = 10_000, .iterations = 20 }, true, meta);
            try runBenchmark(io, allocator, .{ .rows = 100_000, .iterations = 4 }, true, meta);
        },
        .default => try runBenchmark(io, allocator, .{ .rows = 200_000, .iterations = 80 }, false, meta),
    }
}
const std = @import("std");
const zarrow = @import("zarrow");
const csv_meta = @import("csv_meta.zig");

const Mode = enum { default, smoke, full, matrix, matrix_no_header, ci, ci_no_header };

const BenchConfig = struct {
    rows: usize,
    iterations: usize,
};

fn parseMode(init: std.process.Init, allocator: std.mem.Allocator) !Mode {
    var args = try init.minimal.args.iterateAllocator(allocator);
    defer args.deinit();

    _ = args.next();
    const mode_str = args.next() orelse return .default;

    if (std.mem.eql(u8, mode_str, "smoke")) return .smoke;
    if (std.mem.eql(u8, mode_str, "full")) return .full;
    if (std.mem.eql(u8, mode_str, "matrix")) return .matrix;
    if (std.mem.eql(u8, mode_str, "matrix-no-header")) return .matrix_no_header;
    if (std.mem.eql(u8, mode_str, "ci")) return .ci;
    if (std.mem.eql(u8, mode_str, "ci-no-header")) return .ci_no_header;
    return .default;
}

fn printCsvHeader() void {
    std.debug.print("benchmark,rows,iterations,elapsed_ns,rows_per_sec,ns_per_row,checksum,git_sha,timestamp\n", .{});
}

fn runBenchmark(io: std.Io, allocator: std.mem.Allocator, cfg: BenchConfig, emit_csv: bool, meta: csv_meta.CsvMeta) !void {
    // Nullable int32 source (every 7th null) and a pseudo-random index permutation with repeats.
    var builder = try zarrow.Int32Builder.init(allocator, cfg.rows);
    defer builder.deinit();
    for (0..cfg.rows) |i| {
        if (i % 7 == 0) try builder.appendNull() else try builder.append(@intCast(i));
    }
    var source = try builder.finish();
    defer source.release();

    const indices = try allocator.alloc(usize, cfg.rows);
    defer allocator.free(indices);
    for (indices, 0..) |*idx, i| idx.* = (i * 7919 + 13) % cfg.rows;

    var checksum: i64 = 0;
    const timer_start = std.Io.Timestamp.now(io, .awake);

    var iter: usize = 0;
    while (iter < cfg.iterations) : (iter += 1) {
        var out = try zarrow.compute.datumTake(zarrow.compute.Datum.fromArray(source), indices);
        defer out.release();
        const taken = zarrow.Int32Array{ .data = out.array.data() };
        const k = iter % cfg.rows;
        if (!taken.isNull(k)) checksum += try taken.value(k);
    }

    const elapsed_ns: u64 = @intCast(timer_start.untilNow(io, .awake).toNanoseconds());
    const total_rows = cfg.rows * cfg.iterations;
    const rows_per_sec = (@as(f64, @floatFromInt(total_rows)) * 1_000_000_000.0) / @as(f64, @floatFromInt(elapsed_ns));
    const ns_per_row = @as(f64, @floatFromInt(elapsed_ns)) / @as(f64, @floatFromInt(total_rows));

    if (emit_csv) {
        std.debug.print("take,{d},{d},{d},{d:.2},{d:.2},{d},{s},{d}\n", .{
            cfg.rows,
            cfg.iterations,
            elapsed_ns,
            rows_per_sec,
            ns_per_row,
            checksum,
            meta.git_sha,
            meta.timestamp,
        });
        return;
    }

    std.debug.print("benchmark=take rows={d} iterations={d} elapsed_ns={d} rows_per_sec={d:.2} ns_per_row={d:.2} checksum={d}\n", .{
        cfg.rows,
        cfg.iterations,
        elapsed_ns,
        rows_per_sec,
        ns_per_row,
        checksum,
    });
}

pub fn main(init: std.process.Init) !void {
    const io = init.io;
    const allocator = std.heap.page_allocator;
    const mode = try parseMode(init, allocator);
    const meta = try csv_meta.resolve(init, allocator);
    defer meta.deinit(allocator);

    switch (mode) {
        .smoke => try runBenchmark(io, allocator, .{ .rows = 10_000, .iterations = 20 }, false, meta),
        .full => try runBenchmark(io, allocator, .{ .rows = 500_000, .iterations = 120 }, false, meta),
        .matrix => {
            printCsvHeader();
