312	        const r = try offsetRange(T, offsets, j, bytes.len);
313	        total = std.math.add(usize, total, r[1] - r[0]) catch return error.Overflow;
314	    }
315	    if (total > std.math.maxInt(T)) return error.Overflow;
316	
317	    const out_len = indices.len;
318	    var out_offsets = buffer.OwnedBuffer.initUninit(allocator, (out_len + 1) * @sizeOf(T)) catch return error.OutOfMemory;
319	    errdefer out_offsets.deinit();
320	    var out_bytes = buffer.OwnedBuffer.initUninit(allocator, total) catch return error.OutOfMemory;
321	    errdefer out_bytes.deinit();
322	    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
323	    errdefer validity.deinit();
324	
325	    const o = out_offsets.typedSlice(T);
326	    o[0] = 0;
327	    var pos: usize = 0;
328	    for (indices, 0..) |maybe, i| {
329	        if (maybe) |idx| {
330	            const j = src.offset + idx;
331	            if (validAt(src_validity, j)) {
332	                const lo: usize = @intCast(offsets[j]);
333	                const n: usize = @intCast(offsets[j + 1] - offsets[j]);
334	                @memcpy(out_bytes.data[pos..][0..n], bytes[lo..][0..n]);
335	                pos += n;
336	                bitmap.setBit(validity.data, i);
337	            }
338	        }
339	        o[i + 1] = @intCast(pos);
340	    }
341	
342	    var buffers: [3]buffer.SharedBuffer = undefined;
343	    buffers[0] = if (null_count == 0) blk: {
344	        validity.deinit();
345	        break :blk buffer.SharedBuffer.empty;
346	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
347	    errdefer buffers[0].release();
348	    buffers[1] = out_offsets.toShared((out_len + 1) * @sizeOf(T)) catch return error.OutOfMemory;
349	    errdefer buffers[1].release();
350	    buffers[2] = out_bytes.toShared(total) catch return error.OutOfMemory;
351	    errdefer buffers[2].release();
352	
353	    return ArrayRef.fromOwnedInlineBuffers(allocator, .{
354	        .data_type = src.data_type,
355	        .length = out_len,
356	        .null_count = null_count,
357	        .buffers = buffers[0..],
358	    }) catch return error.OutOfMemory;
359	}
