361	/// Direct gather for list/large_list: rebuilds offsets + validity and takes the child once
362	/// with the expanded child indices (recursing into the fast kernels). Returns null for other layouts.
363	fn takeListArray(
364	    comptime T: type,
365	    allocator: std.mem.Allocator,
366	    src: *const array_mod.ArrayData,
367	    indices: []const ?usize,
368	) KernelError!?ArrayRef {
369	    if (src.buffers.len != 2 or src.children.len != 1) return null;
370	    const offsets = src.buffers[1].typedSlice(T) catch return error.InvalidInput;
371	    const child = src.children[0];
372	    const child_len = child.data().length;
373	    const src_end = std.math.add(usize, src.offset, src.length) catch return error.Overflow;
374	    if (offsets.len <= src_end) return error.InvalidInput;
375	    const src_validity = src.validity();
376	
377	    var total: usize = 0;
378	    var null_count: usize = 0;
379	    for (indices) |maybe| {
380	        const idx = maybe orelse {
381	            null_count += 1;
382	            continue;
383	        };
384	        if (idx >= src.length) return error.InvalidInput;
385	        const j = src.offset + idx;
386	        if (!validAt(src_validity, j)) {
387	            null_count += 1;
388	            continue;
389	        }
390	        const r = try offsetRange(T, offsets, j, child_len);
391	        total = std.math.add(usize, total, r[1] - r[0]) catch return error.Overflow;
392	    }
393	    if (total > std.math.maxInt(T)) return error.Overflow;
394	
395	    const child_indices = allocator.alloc(?usize, total) catch return error.OutOfMemory;
396	    defer allocator.free(child_indices);
397	    const out_len = indices.len;
398	    var out_offsets = buffer.OwnedBuffer.initUninit(allocator, (out_len + 1) * @sizeOf(T)) catch return error.OutOfMemory;
399	    errdefer out_offsets.deinit();
400	    var validity = buffer.OwnedBuffer.init(allocator, bitmap.byteLength(out_len)) catch return error.OutOfMemory;
401	    errdefer validity.deinit();
402	
403	    const o = out_offsets.typedSlice(T);
404	    o[0] = 0;
405	    var pos: usize = 0;
406	    for (indices, 0..) |maybe, i| {
407	        if (maybe) |idx| {
408	            const j = src.offset + idx;
409	            if (validAt(src_validity, j)) {
410	                const lo: usize = @intCast(offsets[j]);
411	                const hi: usize = @intCast(offsets[j + 1]);
412	                for (child_indices[pos..][0 .. hi - lo], lo..) |*ci, k| ci.* = k;
413	                pos += hi - lo;
414	                bitmap.setBit(validity.data, i);
415	            }
416	        }
417	        o[i + 1] = @intCast(pos);
418	    }
419	
420	    var taken = try datumTakeArrayLikeNullable(allocator, Datum.fromArray(child), child.data().data_type, child_indices);

420	    var taken = try datumTakeArrayLikeNullable(allocator, Datum.fromArray(child), child.data().data_type, child_indices);
421	    if (taken != .array) {
422	        taken.release();
423	        return error.InvalidInput;
424	    }
425	    const children = allocator.alloc(ArrayRef, 1) catch {
426	        taken.release();
427	        return error.OutOfMemory;
428	    };
429	    children[0] = taken.array;
430	    errdefer {
431	        children[0].release();
432	        allocator.free(children);
433	    }
434	
435	    var buffers: [2]buffer.SharedBuffer = undefined;
436	    buffers[0] = if (null_count == 0) blk: {
437	        validity.deinit();
438	        break :blk buffer.SharedBuffer.empty;
439	    } else validity.toShared(bitmap.byteLength(out_len)) catch return error.OutOfMemory;
440	    errdefer buffers[0].release();
441	    buffers[1] = out_offsets.toShared((out_len + 1) * @sizeOf(T)) catch return error.OutOfMemory;
442	    errdefer buffers[1].release();
443	
444	    return ArrayRef.fromOwnedInlineBuffers(allocator, .{
445	        .data_type = src.data_type,
446	        .length = out_len,
447	        .null_count = null_count,
448	        .buffers = buffers[0..],
449	        .children = children,
450	    }) catch return error.OutOfMemory;
451	}
