453	fn datumTakeArrayLikeNullable(
454	    allocator: std.mem.Allocator,
455	    datum: Datum,
456	    out_type: DataType,
457	    indices: []const ?usize,
458	) KernelError!Datum {
459	    if (indices.len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
460	    if (datum == .array) {
461	        const src = datum.array.data();
462	        const fast = switch (src.data_type) {
463	            .string, .binary => try takeBinaryArray(i32, allocator, src, indices),
464	            .large_string, .large_binary => try takeBinaryArray(i64, allocator, src, indices),
465	            .list => try takeListArray(i32, allocator, src, indices),
466	            .large_list => try takeListArray(i64, allocator, src, indices),
467	            else => try takeFixedWidthArray(allocator, src, indices),
468	        };
469	        if (fast) |out| return Datum.fromArray(out);
470	    }
471	
472	    var pieces: std.ArrayList(ArrayRef) = .empty;
473	    defer {
474	        for (pieces.items) |*piece| piece.release();
475	        pieces.deinit(allocator);
476	    }
477	    try pieces.ensureTotalCapacity(allocator, indices.len);
478	
479	    for (indices) |choice| {
480	        const piece = if (choice) |idx|
481	            try accessors.datumElementArrayAt(allocator, datum, idx)
482	        else
483	            try builders.buildNullLikeArray(allocator, out_type, 1);
484	        pieces.appendAssumeCapacity(piece);
485	    }
486	
487	    const out = concat_array_refs.concatArrayRefs(allocator, out_type, pieces.items) catch |err| return common.mapConcatError(err);
488	    return Datum.fromArray(out);
489	}
