491	fn predicateDecisionAt(predicate: Datum, logical_index: usize, options: FilterOptions) KernelError!PredicateDecision {
492	    return switch (predicate) {
493	        .scalar => |s| blk: {
494	            if (s.data_type != .bool) break :blk error.InvalidInput;
495	            if (s.isNull()) break :blk if (options.drop_nulls) .drop else .emit_null;
496	            break :blk if (s.value.bool) .keep else .drop;
497	        },
498	        .array => |arr| blk: {
499	            if (arr.data().data_type != .bool) break :blk error.InvalidInput;
500	            if (logical_index >= arr.data().length) break :blk error.InvalidInput;
501	            if (arr.data().isNull(logical_index)) break :blk if (options.drop_nulls) .drop else .emit_null;
502	            const bool_array = array_mod.BooleanArray{ .data = arr.data() };
503	            const keep = bool_array.value(logical_index) catch |err| return mapArrayReadError(err);
504	            break :blk if (keep) .keep else .drop;
505	        },
506	        .chunked => |chunks| blk: {
507	            if (chunks.dataType() != .bool) break :blk error.InvalidInput;
508	            const located = lookupChunkAt(chunks, logical_index) orelse break :blk error.InvalidInput;
509	            if (located.chunk.data().isNull(located.local_index)) break :blk if (options.drop_nulls) .drop else .emit_null;
510	            const bool_array = array_mod.BooleanArray{ .data = located.chunk.data() };
511	            const keep = bool_array.value(located.local_index) catch |err| return mapArrayReadError(err);
512	            break :blk if (keep) .keep else .drop;
513	        },
514	    };
515	}
