517	/// 8 bits of `bytes` starting at bit `bit` (bits past the end of `bytes` read as 0).
518	fn byteAtBit(bytes: []const u8, bit: usize) u8 {
519	    const i = bit >> 3;
520	    const sh: u3 = @intCast(bit & 7);
521	    const lo = bytes[i] >> sh;
522	    if (sh == 0 or i + 1 >= bytes.len) return lo;
523	    return lo | (bytes[i + 1] << @intCast(8 - @as(u4, sh)));
524	}
525	
526	const SelectionByte = struct { emit: u8, valid: u8 };
527	
528	/// Rows `row .. row+8` of a bool predicate: which rows emit an entry and which of those are valid.
529	fn selectionByte(values: []const u8, validity: []const u8, bit: usize, rows_left: usize, drop_nulls: bool) SelectionByte {
530	    const tail_mask: u8 = if (rows_left >= 8) 0xFF else (@as(u8, 1) << @intCast(rows_left)) - 1;
531	    const valid = if (validity.len > 0) byteAtBit(validity, bit) else 0xFF;
532	    var emit = byteAtBit(values, bit) & valid;
533	    if (!drop_nulls) emit |= ~valid;
534	    return .{ .emit = emit & tail_mask, .valid = valid };
535	}
