537	/// Appends selections for rows [0, len) of a bool predicate array, 8 rows per step.
538	/// `base` is the logical index of the predicate's row 0.
539	fn appendBoolSelections(
540	    allocator: std.mem.Allocator,
541	    selections: *std.ArrayList(?usize),
542	    pred: *const array_mod.ArrayData,
543	    len: usize,
544	    base: usize,
545	    options: FilterOptions,
546	) KernelError!void {
547	    if (pred.buffers.len < 2) return error.InvalidInput;
548	    const values = pred.buffers[1].data;
549	    const end = std.math.add(usize, pred.offset, len) catch return error.Overflow;
550	    if (bitmap.byteLength(end) > values.len) return error.InvalidInput;
551	    const validity: []const u8 = if (pred.validity()) |v| v.data else &.{};
552	    if (validity.len > 0 and bitmap.byteLength(end) > validity.len) return error.InvalidInput;
553	
554	    var count: usize = 0;
555	    var row: usize = 0;
556	    while (row < len) : (row += 8) {
557	        count += @popCount(selectionByte(values, validity, pred.offset + row, len - row, options.drop_nulls).emit);
558	    }
559	    try selections.ensureUnusedCapacity(allocator, count);
560	
561	    row = 0;
562	    while (row < len) : (row += 8) {
563	        const sb = selectionByte(values, validity, pred.offset + row, len - row, options.drop_nulls);
564	        var emit = sb.emit;
565	        while (emit != 0) : (emit &= emit - 1) {
566	            const bit: u3 = @intCast(@ctz(emit));
567	            const is_valid = (sb.valid >> bit) & 1 != 0;
568	            selections.appendAssumeCapacity(if (is_valid) base + row + bit else null);
569	        }
570	    }
571	}
