573	/// Build nullable selection indices from a boolean predicate.
574	///
575	/// `keep` emits the logical input index, `drop` emits nothing, and `emit_null`
576	/// emits `null` to preserve output row count for null-predicate semantics.
577	pub fn datumFilterSelectionIndices(
578	    allocator: std.mem.Allocator,
579	    predicate: Datum,
580	    logical_len: usize,
581	    options: FilterOptions,
582	) KernelError![]?usize {
583	    var selections: std.ArrayList(?usize) = .empty;
584	    defer selections.deinit(allocator);
585	
586	    switch (predicate) {
587	        .array => |arr| {
588	            if (arr.data().data_type != .bool) return error.InvalidInput;
589	            if (logical_len > arr.data().length) return error.InvalidInput;
590	            try appendBoolSelections(allocator, &selections, arr.data(), logical_len, 0, options);
591	        },
592	        .chunked => |chunks| {
593	            if (chunks.dataType() != .bool) return error.InvalidInput;
594	            var done: usize = 0;
595	            for (chunks.chunks()) |chunk| {
596	                if (done == logical_len) break;
597	                const take = @min(chunk.data().length, logical_len - done);
598	                try appendBoolSelections(allocator, &selections, chunk.data(), take, done, options);
599	                done += take;
600	            }
601	            if (done != logical_len) return error.InvalidInput;
602	        },
603	        .scalar => {
604	            var i: usize = 0;
605	            while (i < logical_len) : (i += 1) {
606	                switch (try predicateDecisionAt(predicate, i, options)) {
607	                    .drop => {},
608	                    .keep => try selections.append(allocator, i),
609	                    .emit_null => try selections.append(allocator, null),
610	                }
611	            }
612	        },
613	    }
614	    return selections.toOwnedSlice(allocator);
615	}
