617	/// Gather/take rows from a datum according to logical indices.
618	///
619	/// For chunked inputs this helper preserves chunked output and avoids forcing
620	/// concat pre-normalization.
621	pub fn datumTake(datum: Datum, indices: []const usize) KernelError!Datum {
622	    const allocator = common.inferDatumAllocator(datum) orelse std.heap.page_allocator;
623	    const out_type = datum.dataType();
624	
625	    if (indices.len == 0) {
626	        return switch (datum) {
627	            .chunked => |chunks| Datum.fromChunked(chunks.slice(allocator, 0, 0) catch |err| return common.mapChunkedError(err)),
628	            else => builders.datumBuildEmptyLikeWithAllocator(allocator, out_type),
629	        };
630	    }
631	
632	    return switch (datum) {
633	        .chunked => |chunks| blk: {
634	            var nullable = allocator.alloc(?usize, indices.len) catch break :blk error.OutOfMemory;
635	            defer allocator.free(nullable);
636	            for (indices, 0..) |index, i| nullable[i] = index;
637	            break :blk try datumTakeChunkedNullable(allocator, chunks, out_type, nullable);
638	        },
639	        else => blk: {
640	            var nullable = allocator.alloc(?usize, indices.len) catch break :blk error.OutOfMemory;
641	            defer allocator.free(nullable);
642	            for (indices, 0..) |index, i| nullable[i] = index;
643	            break :blk try datumTakeArrayLikeNullable(allocator, datum, out_type, nullable);
644	        },
645	    };
646	}
