648	/// Gather/take rows with nullable indices where `null` emits an all-null row.
649	///
650	/// For chunked inputs this helper preserves chunked output and avoids forcing
651	/// concat pre-normalization.
652	pub fn datumTakeNullable(datum: Datum, indices: []const ?usize) KernelError!Datum {
653	    const allocator = common.inferDatumAllocator(datum) orelse std.heap.page_allocator;
654	    const out_type = datum.dataType();
655	    return switch (datum) {
656	        .chunked => |chunks| datumTakeChunkedNullable(allocator, chunks, out_type, indices),
657	        else => datumTakeArrayLikeNullable(allocator, datum, out_type, indices),
658	    };
659	}
