661	/// Row-wise selection primitive shared by choose/case_when/filter style operators.
662	///
663	/// `indices[i]` selects which entry in `values` contributes output row `i`.
664	/// Each candidate value may be array/chunked/scalar (scalar broadcasts).
665	pub fn datumSelect(indices: []const usize, values: []const Datum) KernelError!Datum {
666	    if (values.len == 0) return error.InvalidArity;
667	    if (!sameDataTypes(values)) return error.InvalidInput;
668	
669	    const output_len = try inferNaryExecLen(values);
670	    if (indices.len != output_len) return error.InvalidInput;
671	
672	    const allocator = common.inferDatumsAllocator(values);
673	    const out_type = values[0].dataType();
674	    if (indices.len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
675	
676	    var pieces: std.ArrayList(ArrayRef) = .empty;
677	    defer {
678	        for (pieces.items) |*piece| piece.release();
679	        pieces.deinit(allocator);
680	    }
681	    try pieces.ensureTotalCapacity(allocator, indices.len);
682	
683	    for (indices, 0..) |choice, logical_index| {
684	        if (choice >= values.len) return error.InvalidInput;
685	        const piece = try accessors.datumElementArrayAt(allocator, values[choice], logical_index);
686	        pieces.appendAssumeCapacity(piece);
687	    }
688	
689	    const out = concat_array_refs.concatArrayRefs(allocator, out_type, pieces.items) catch |err| return common.mapConcatError(err);
690	    return Datum.fromArray(out);
691	}
