697	    if (values.len == 0) return error.InvalidArity;
698	    if (!sameDataTypes(values)) return error.InvalidInput;
699	
700	    const output_len = try inferNaryExecLen(values);
701	    if (indices.len != output_len) return error.InvalidInput;
702	
703	    const allocator = common.inferDatumsAllocator(values);
704	    const out_type = values[0].dataType();
705	    if (indices.len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
706	
707	    var pieces: std.ArrayList(ArrayRef) = .empty;
708	    defer {
709	        for (pieces.items) |*piece| piece.release();
710	        pieces.deinit(allocator);
711	    }
712	    try pieces.ensureTotalCapacity(allocator, indices.len);
