726	/// Chunk-aware filter helper for array/chunked/scalar datums with bool predicates.
727	///
728	/// This helper composes `datumFilterSelectionIndices` + `datumTakeNullable`,
729	/// preserving chunked output when the input datum is chunked.
730	pub fn datumFilterChunkAware(datum: Datum, predicate: Datum, options: FilterOptions) KernelError!Datum {
731	    const input_len = try inferBinaryExecLen(datum, predicate);
732	    const allocator = common.inferDatumsAllocator(&[_]Datum{ datum, predicate });
733	    const selections = try datumFilterSelectionIndices(allocator, predicate, input_len, options);
734	    defer allocator.free(selections);
735	    return datumTakeNullable(datum, selections);
736	}
