738	/// Generic filter primitive for array/chunked/scalar datums with bool predicates.
739	///
740	/// This preserves the historical array-output shape for compatibility.
741	pub fn datumFilter(datum: Datum, predicate: Datum, options: FilterOptions) KernelError!Datum {
742	    const output_len = try inferBinaryExecLen(datum, predicate);
743	    const allocator = common.inferDatumsAllocator(&[_]Datum{ datum, predicate });
744	    const out_type = datum.dataType();
745	
746	    if (output_len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
747	    if (datum == .array) {
748	        const selections = try datumFilterSelectionIndices(allocator, predicate, output_len, options);
749	        defer allocator.free(selections);
750	        return datumTakeArrayLikeNullable(allocator, datum, out_type, selections);
751	    }
752	
753	    var pieces: std.ArrayList(ArrayRef) = .empty;
754	    defer {
755	        for (pieces.items) |*piece| piece.release();
756	        pieces.deinit(allocator);
757	    }
758	
759	    switch (predicate) {
760	        // Chunked predicate: use an incremental cursor (O(1) amortized per element)
761	        // instead of calling lookupChunkAt (O(n) per element) inside the loop.
762	        .chunked => |chunks| {
763	            if (chunks.dataType() != .bool) return error.InvalidInput;
764	            var chunk_idx: usize = 0;
765	            var local_idx: usize = 0;
766	            var i: usize = 0;
767	            while (i < output_len) : (i += 1) {
768	                while (chunk_idx < chunks.numChunks() and
769	                    local_idx >= chunks.chunk(chunk_idx).data().length)
770	                {
771	                    chunk_idx += 1;
772	                    local_idx = 0;
773	                }
774	                if (chunk_idx >= chunks.numChunks()) return error.InvalidInput;
775	                const chunk = chunks.chunk(chunk_idx);
776	                const decision: PredicateDecision = if (chunk.data().isNull(local_idx))
777	                    (if (options.drop_nulls) .drop else .emit_null)
778	                else blk: {
779	                    const bool_array = array_mod.BooleanArray{ .data = chunk.data() };
780	                    const keep = bool_array.value(local_idx) catch |err| return mapArrayReadError(err);
781	                    break :blk if (keep) .keep else .drop;
782	                };
783	                local_idx += 1;
784	                const piece = switch (decision) {
785	                    .drop => continue,
786	                    .keep => try accessors.datumElementArrayAt(allocator, datum, i),
787	                    .emit_null => try builders.buildNullLikeArray(allocator, out_type, 1),
788	                };
789	                try appendOwnedArrayRef(allocator, &pieces, piece);
790	            }
791	        },
792	        else => {
793	            var i: usize = 0;
794	            while (i < output_len) : (i += 1) {
795	                const decision = try predicateDecisionAt(predicate, i, options);
796	                const piece = switch (decision) {
797	                    .drop => continue,
798	                    .keep => try accessors.datumElementArrayAt(allocator, datum, i),
799	                    .emit_null => try builders.buildNullLikeArray(allocator, out_type, 1),
800	                };
801	                try appendOwnedArrayRef(allocator, &pieces, piece);
802	            }
803	        },
804	    }
805	
806	    if (pieces.items.len == 0) return builders.datumBuildEmptyLikeWithAllocator(allocator, out_type);
807	
808	    const out = concat_array_refs.concatArrayRefs(allocator, out_type, pieces.items) catch |err| return common.mapConcatError(err);
809	    return Datum.fromArray(out);
