 30	// Read a single bit using Arrow's least-significant-bit-first order.
 31	pub fn bitIsSet(data: []const u8, bit_index: usize) bool {
 32	    // Cases:
 33	    // - data = { 0b0000_0101 }, bitIsSet(data, 0) == true
 34	    // - data = { 0b0000_0101 }, bitIsSet(data, 1) == false
 35	    // - data = { 0b0000_0101 }, bitIsSet(data, 2) == true
 36	    // - data = { 0b0000_0101, 0b0000_0010 }, bitIsSet(data, 9) == true
 37	    // - data = { 0b0000_0101, 0b0000_0010 }, bitIsSet(data, 8) == false
 38	    const byte = data[bit_index >> 3];
 39	    return (byte & bitMask(bit_index)) != 0;
 40	}
