 42	// Set a single bit in-place using Arrow's least-significant-bit-first bit order.
 43	// Cases:
 44	// - data = { 0b0000_0000 }, setBit(data, 0) => { 0b0000_0001 }
 45	// - data = { 0b0000_0000 }, setBit(data, 7) => { 0b1000_0000 }
 46	// - data = { 0b0000_0000, 0b0000_0000 }, setBit(data, 9) => { 0b0000_0000, 0b0000_0010 }
 47	pub fn setBit(data: []u8, bit_index: usize) void {
 48	    data[bit_index >> 3] |= bitMask(bit_index);
 49	}
 50	
 51	// Clear a single bit in-place using Arrow's least-significant-bit-first bit order.
 52	// Cases:
 53	// - data = { 0b1111_1111 }, clearBit(data, 0) => { 0b1111_1110 }
 54	// - data = { 0b1111_1111 }, clearBit(data, 7) => { 0b0111_1111 }
 55	// - data = { 0b1111_1111, 0b1111_1111 }, clearBit(data, 9) => { 0b1111_1111, 0b1111_1101 }
 56	pub fn clearBit(data: []u8, bit_index: usize) void {
 57	    data[bit_index >> 3] &= ~bitMask(bit_index);
 58	}
