 61	// Cases:
 62	// - data = { 0b0000_0000 }, writeBit(data, 1, true) => { 0b0000_0010 }
 63	// - data = { 0b0000_0010 }, writeBit(data, 1, false) => { 0b0000_0000 }
 64	// - data = { 0b0000_0000, 0b0000_0000 }, writeBit(data, 9, true) => { 0b0000_0000, 0b0000_0010 }
 65	pub fn writeBit(data: []u8, bit_index: usize, value: bool) void {
 66	    if (value) setBit(data, bit_index) else clearBit(data, bit_index);
 67	}
