124	// Count set bits in the half-open range [start_bit, end_bit).
125	// Correctly handles non-zero start offsets, avoiding O(n) element-by-element scanning.
126	pub fn countSetBitsInRange(data: []const u8, start_bit: usize, end_bit: usize) usize {
127	    if (start_bit >= end_bit) return 0;
128	    // Fast path: zero-based range delegates to the existing full-scan helper.
129	    if (start_bit == 0) return countSetBit(data, end_bit);
130	
131	    const first_byte = start_bit >> 3;
132	    const last_byte = (end_bit - 1) >> 3;
133	
134	    var count: usize = 0;
135	
136	    if (first_byte == last_byte) {
137	        // All bits are within a single byte.
138	        const lo_bit = @as(u3, @intCast(start_bit & 7));
139	        const hi_bit = @as(u3, @intCast((end_bit - 1) & 7));
140	        const hi_shift = @as(u4, hi_bit) + 1; // range 1..8
141	        const hi_mask: u8 = if (hi_shift >= 8) 0xFF else (@as(u8, 1) << @as(u3, @intCast(hi_shift))) - 1;
142	        const lo_mask: u8 = ~((@as(u8, 1) << lo_bit) - 1);
143	        return @popCount(data[first_byte] & lo_mask & hi_mask);
144	    }
145	
146	    // First byte: bits from (start_bit & 7) through the high end of the byte.
147	    const lo_bit = @as(u3, @intCast(start_bit & 7));
148	    const first_mask: u8 = ~((@as(u8, 1) << lo_bit) - 1);
149	    count += @popCount(data[first_byte] & first_mask);
150	
151	    // Full middle bytes: delegate to countSetBit so the SIMD loop is reused
152	    // automatically when the middle region is large enough.
153	    const mid = data[first_byte + 1 .. last_byte];
154	    if (mid.len > 0) count += countSetBit(mid, mid.len * 8);
155	
156	    // Last byte: bits from 0 through (end_bit-1) & 7.
157	    const hi_bit = @as(u3, @intCast((end_bit - 1) & 7));
158	    const hi_shift = @as(u4, hi_bit) + 1;
159	    const last_mask: u8 = if (hi_shift >= 8) 0xFF else (@as(u8, 1) << @as(u3, @intCast(hi_shift))) - 1;
160	    count += @popCount(data[last_byte] & last_mask);
161	
162	    return count;
163	}
