171	// Copy `len` bits from `src` (starting at bit `src_off`) into `dst` (starting at bit `dst_off`).
172	// Bits of `dst` outside [dst_off, dst_off + len) are preserved. One destination byte per step
173	// instead of one bit, so validity/boolean concat and gather run at near-memcpy speed.
174	pub fn copyBits(dst: []u8, dst_off: usize, src: []const u8, src_off: usize, len: usize) void {
175	    var d = dst_off;
176	    var s = src_off;
177	    const end = dst_off + len;
178	    while (d < end and (d & 7) != 0) : ({
179	        d += 1;
180	        s += 1;
181	    }) writeBit(dst, d, bitIsSet(src, s));
182	    const full = (end - d) >> 3;
183	    if (full > 0) {
184	        const di = d >> 3;
185	        const si = s >> 3;
186	        const shift: u3 = @intCast(s & 7);
187	        if (shift == 0) {
188	            @memcpy(dst[di..][0..full], src[si..][0..full]);
189	        } else {
190	            // Bits s .. s+8*full-1 are in range, so src[si + k + 1] is always readable here.
191	            const back: u3 = @intCast(8 - @as(u4, shift));
192	            for (0..full) |k| dst[di + k] = (src[si + k] >> shift) | (src[si + k + 1] << back);
193	        }
194	        d += full * 8;
195	        s += full * 8;
196	    }
197	    while (d < end) : ({
198	        d += 1;
199	        s += 1;
200	    }) writeBit(dst, d, bitIsSet(src, s));
201	}
