203	// Set bits [off, off + len) of `dst` to 1.
204	pub fn setBits(dst: []u8, off: usize, len: usize) void {
205	    var d = off;
206	    const end = off + len;
207	    while (d < end and (d & 7) != 0) : (d += 1) setBit(dst, d);
208	    const full = (end - d) >> 3;
209	    @memset(dst[d >> 3 ..][0..full], 0xFF);
210	    d += full * 8;
211	    while (d < end) : (d += 1) setBit(dst, d);
212	}
