214	fn clearTrailingBits(bytes: []u8, len: usize, valid: bool) void {
215	    if (len == 0 or bytes.len == 0) return;
216	
217	    const remainder = len & 7;
218	    if (remainder == 0) return;
219	
220	    const last = bytes.len - 1;
221	    const keep_mask = (@as(u8, 1) << @as(u3, @intCast(remainder))) - 1;
222	    bytes[last] &= keep_mask;
223	    if (valid) bytes[last] |= keep_mask;
224	}
