const std = @import("std");
const zarrow = @import("zarrow");

var g_io: std.Io = undefined;
var g_filter: []const u8 = "";

fn now() std.Io.Timestamp {
    return std.Io.Timestamp.now(g_io, .awake);
}
fn since(t: std.Io.Timestamp) u64 {
    return @intCast(t.untilNow(g_io, .awake).toNanoseconds());
}
fn report(name: []const u8, ns: u64, rows: usize) void {
    std.debug.print("{s:<40} ns_per_row={d:.3}\n", .{ name, @as(f64, @floatFromInt(ns)) / @as(f64, @floatFromInt(rows)) });
}
fn want(name: []const u8) bool {
    return g_filter.len == 0 or std.mem.indexOf(u8, name, g_filter) != null;
}

const ROWS: usize = 200_000;
const ITERS: usize = 80;
const names = [_][]const u8{ "alpha", "beta", "gamma", "delta-long-name" };

fn probeBuilder(a: std.mem.Allocator, label: []const u8) !void {
    if (want("builder")) {
        var b = try zarrow.Int32Builder.init(a, ROWS);
        defer b.deinit();
        var cs: i64 = 0;
        const t = now();
        for (0..ITERS) |iter| {
            for (0..ROWS) |i| {
                const v: i32 = @intCast((i + iter) % 1024);
                try b.append(v);
                cs += v;
            }
            var arr = try b.finishReset();
            arr.release();
        }
        report(try std.fmt.allocPrint(a, "builder_{s}", .{label}), since(t), ROWS * ITERS);
        std.mem.doNotOptimizeAway(cs);
    }
    if (want("builder")) {
        // builder with reserve(ROWS) each iteration: isolates per-append cost from growth.
        var b = try zarrow.Int32Builder.init(a, ROWS);
        defer b.deinit();
        var cs: i64 = 0;
        const t = now();
        for (0..ITERS) |iter| {
            try b.reserve(ROWS);
            for (0..ROWS) |i| {
                const v: i32 = @intCast((i + iter) % 1024);
                try b.append(v);
                cs += v;
            }
            var arr = try b.finishReset();
            arr.release();
        }
        report(try std.fmt.allocPrint(a, "builder_reserved_{s}", .{label}), since(t), ROWS * ITERS);
        std.mem.doNotOptimizeAway(cs);
    }
    if (want("builder")) {
        // std ArrayList push from empty each iteration (what arrow-rs Vec push does).
        var cs: i64 = 0;
        const t = now();
        for (0..ITERS) |iter| {
            var list: std.ArrayList(i32) = .empty;
            for (0..ROWS) |i| {
                const v: i32 = @intCast((i + iter) % 1024);
                try list.append(a, v);
                cs += v;
            }
            std.mem.doNotOptimizeAway(list.items.ptr);
            list.deinit(a);
        }
        report(try std.fmt.allocPrint(a, "arraylist_{s}", .{label}), since(t), ROWS * ITERS);
        std.mem.doNotOptimizeAway(cs);
    }
    if (want("builder")) {
        // ArrayList with doubling growth only (no append overhead differences): alloc pattern cost.
        const t = now();
        for (0..ITERS) |_| {
            var cap: usize = 64;
            var buf = try a.alignedAlloc(u8, .@"64", cap);
            while (cap < ROWS * 4) {
                buf = try a.realloc(buf, cap * 2);
                @memset(buf[cap..], 0);
                cap *= 2;
            }
            @memset(buf, 1);
            a.free(buf);
        }
        report(try std.fmt.allocPrint(a, "grow_realloc_zero_{s}", .{label}), since(t), ROWS * ITERS);
    }
}

fn buildInt32(a: std.mem.Allocator, n: usize) !zarrow.ArrayRef {
    var b = try zarrow.Int32Builder.init(a, n);
    defer b.deinit();
    for (0..n) |i| {
        if (i % 7 == 0) try b.appendNull() else try b.append(@intCast(i));
    }
    return b.finish();
}
fn buildString(a: std.mem.Allocator, n: usize) !zarrow.ArrayRef {
    var b = try zarrow.StringBuilder.init(a, n, n * 8);
    defer b.deinit();
    for (0..n) |i| {
        if (i % 7 == 0) try b.appendNull() else try b.append(names[i & 3]);
    }
    return b.finish();
}

/// K2: branchless gather + packed validity; mirrors arrow-rs take_native + take_bits.
fn takeK2(a: std.mem.Allocator, vals: []const i32, valid: []const u8, idx: []const usize) !usize {
    const out = try a.alignedAlloc(i32, .@"64", idx.len);
    defer a.free(out);
    const ob = try a.alignedAlloc(u8, .@"64", (idx.len + 7) / 8);
    defer a.free(ob);
    for (idx) |j| if (j >= vals.len) return error.Bad;
    for (idx, out) |j, *o| o.* = vals[j];
    const full = idx.len / 8;
    for (0..full) |byte_i| {
        var byte: u8 = 0;
        inline for (0..8) |bit| {
            const j = idx[byte_i * 8 + bit];
            byte |= ((valid[j >> 3] >> @intCast(j & 7)) & 1) << bit;
        }
        ob[byte_i] = byte;
    }
    var nulls: usize = 0;
    for (ob[0..full]) |byte| nulls += 8 - @as(usize, @popCount(byte));
    std.mem.doNotOptimizeAway(out.ptr);
    return nulls;
}

/// K3: K2 with bounds check fused into the value loop.
fn takeK3(a: std.mem.Allocator, vals: []const i32, valid: []const u8, idx: []const usize) !usize {
    const out = try a.alignedAlloc(i32, .@"64", idx.len);
    defer a.free(out);
    const ob = try a.alignedAlloc(u8, .@"64", (idx.len + 7) / 8);
    defer a.free(ob);
    const full = idx.len / 8;
    for (0..full) |byte_i| {
        var byte: u8 = 0;
        inline for (0..8) |bit| {
            const j = idx[byte_i * 8 + bit];
            if (j >= vals.len) return error.Bad;
            out[byte_i * 8 + bit] = vals[j];
            byte |= ((valid[j >> 3] >> @intCast(j & 7)) & 1) << bit;
        }
        ob[byte_i] = byte;
    }
    var nulls: usize = 0;
    for (ob[0..full]) |byte| nulls += 8 - @as(usize, @popCount(byte));
    std.mem.doNotOptimizeAway(out.ptr);
    return nulls;
}

fn probeTake(a: std.mem.Allocator, label: []const u8) !void {
    var src = try buildInt32(a, ROWS);
    defer src.release();
    const indices = try a.alloc(usize, ROWS);
    defer a.free(indices);
    for (indices, 0..) |*idx, i| idx.* = (i * 7919 + 13) % ROWS;

    if (want("take")) {
        var cs: i64 = 0;
        const t = now();
        for (0..ITERS) |iter| {
            var out = try zarrow.compute.datumTake(zarrow.compute.Datum.fromArray(src), indices);
            defer out.release();
            const taken = zarrow.Int32Array{ .data = out.array.data() };
            if (!taken.isNull(iter)) cs += try taken.value(iter);
        }
        report(try std.fmt.allocPrint(a, "take_datumTake_{s}", .{label}), since(t), ROWS * ITERS);
        std.mem.doNotOptimizeAway(cs);
    }
    if (want("take")) {
        // only the ?usize conversion datumTake does (alloc + fill + free)
        const t = now();
        for (0..ITERS) |_| {
            var nullable = try a.alloc(?usize, indices.len);
            for (indices, 0..) |index, i| nullable[i] = index;
            std.mem.doNotOptimizeAway(nullable.ptr);
            a.free(nullable);
        }
        report(try std.fmt.allocPrint(a, "take_optional_conversion_{s}", .{label}), since(t), ROWS * ITERS);
    }
    const sd = src.data();
    const vals = (try sd.buffers[1].typedSlice(i32))[0..ROWS];
    const valid = sd.buffers[0].data;
    if (want("take")) {
        var n: usize = 0;
        const t = now();
        for (0..ITERS) |_| n += try takeK2(a, vals, valid, indices);
        report(try std.fmt.allocPrint(a, "take_K2_branchless_{s}", .{label}), since(t), ROWS * ITERS);
        std.mem.doNotOptimizeAway(n);
    }
    if (want("take")) {
        var n: usize = 0;
        const t = now();
        for (0..ITERS) |_| n += try takeK3(a, vals, valid, indices);
        report(try std.fmt.allocPrint(a, "take_K3_fused_check_{s}", .{label}), since(t), ROWS * ITERS);
        std.mem.doNotOptimizeAway(n);
    }
}

fn probeFilter(a: std.mem.Allocator, label: []const u8) !void {
    var strs = try buildString(a, ROWS);
    defer strs.release();
    var pb = try zarrow.BooleanBuilder.init(a, ROWS);
    defer pb.deinit();
    for (0..ROWS) |i| {
        if (i % 11 == 0) try pb.appendNull() else try pb.append((i * 7919) % 2 == 0);
    }
    var pred = try pb.finish();
    defer pred.release();
    const D = zarrow.compute.Datum;
    if (want("filter")) {
        var cs: usize = 0;
        const t = now();
        for (0..ITERS) |_| {
            var out = try zarrow.compute.datumFilter(D.fromArray(strs), D.fromArray(pred), .{});
            defer out.release();
            cs += out.array.data().length;
        }
        report(try std.fmt.allocPrint(a, "filter_datumFilter_{s}", .{label}), since(t), ROWS * ITERS);
        std.mem.doNotOptimizeAway(cs);
