    if (want("filter")) {
        var cs: usize = 0;
        const t = now();
        for (0..ITERS) |_| {
            const sel = try zarrow.compute.datumFilterSelectionIndices(a, D.fromArray(pred), ROWS, .{});
            cs += sel.len;
            a.free(sel);
        }
        report(try std.fmt.allocPrint(a, "filter_selection_only_{s}", .{label}), since(t), ROWS * ITERS);
        std.mem.doNotOptimizeAway(cs);
    }
    if (want("filter")) {
        const sel = try zarrow.compute.datumFilterSelectionIndices(a, D.fromArray(pred), ROWS, .{});
        defer a.free(sel);
        var cs: usize = 0;
        const t = now();
        for (0..ITERS) |_| {
            var out = try zarrow.compute.datumTakeNullable(D.fromArray(strs), sel);
            defer out.release();
            cs += out.array.data().length;
        }
        report(try std.fmt.allocPrint(a, "filter_take_only_{s}", .{label}), since(t), ROWS * ITERS);
