        const bytes = sd.buffers[2].data;
        const sel = try zarrow.compute.datumFilterSelectionIndices(a, D.fromArray(pred), ROWS, .{});
        defer a.free(sel);
        const out = try a.alloc(u8, ROWS * 16 + 64);
        defer a.free(out);
        var t = now();
        var pos: usize = 0;
        for (0..ITERS) |_| {
            pos = 0;
            for (sel) |m| {
