                const lo: usize = @intCast(offs[j]);
                const n: usize = @intCast(offs[j + 1] - offs[j]);
                @memcpy(out[pos..][0..n], bytes[lo..][0..n]);
                pos += n;
            }
        }
        report(try std.fmt.allocPrint(a, "filter_bytes_memcpy_{s}", .{label}), since(t), ROWS * ITERS);
