const std = @import("std");
const zarrow = @import("zarrow");

var g_io: std.Io = undefined;
var g_filter: []const u8 = "";

fn now() std.Io.Timestamp {
    return std.Io.Timestamp.now(g_io, .awake);
}
fn since(t: std.Io.Timestamp) u64 {
    return @intCast(t.untilNow(g_io, .awake).toNanoseconds());
}
fn report(name: []const u8, ns: u64, rows: usize) void {
    std.debug.print("{s:<44} ns_per_row={d:.3}\n", .{ name, @as(f64, @floatFromInt(ns)) / @as(f64, @floatFromInt(rows)) });
}
fn want(name: []const u8) bool {
    return g_filter.len == 0 or std.mem.indexOf(u8, name, g_filter) != null;
}

extern fn ZSTD_compress(dst: ?*anyopaque, cap: usize, src: ?*const anyopaque, n: usize, level: c_int) callconv(.c) usize;
extern fn ZSTD_compressBound(n: usize) callconv(.c) usize;
extern fn ZSTD_decompress(dst: ?*anyopaque, cap: usize, src: ?*const anyopaque, n: usize) callconv(.c) usize;
extern fn ZSTD_createCCtx() callconv(.c) ?*anyopaque;
extern fn ZSTD_compressCCtx(cctx: ?*anyopaque, dst: ?*anyopaque, cap: usize, src: ?*const anyopaque, n: usize, level: c_int) callconv(.c) usize;
extern fn ZSTD_createDCtx() callconv(.c) ?*anyopaque;
extern fn ZSTD_decompressDCtx(dctx: ?*anyopaque, dst: ?*anyopaque, cap: usize, src: ?*const anyopaque, n: usize) callconv(.c) usize;

const names = [_][]const u8{ "alpha", "beta", "gamma", "delta-long-name" };
const int32_type = zarrow.DataType{ .int32 = {} };
const int64_type = zarrow.DataType{ .int64 = {} };
const bool_type = zarrow.DataType{ .bool = {} };
const string_type = zarrow.DataType{ .string = {} };

fn buildBatch4(a: std.mem.Allocator, schema_ref: zarrow.SchemaRef, rows: usize) !zarrow.RecordBatch {
    var id = try zarrow.Int32Builder.init(a, rows);
    defer id.deinit();
    var value = try zarrow.Int64Builder.init(a, rows);
    defer value.deinit();
    var ok = try zarrow.BooleanBuilder.init(a, rows);
    defer ok.deinit();
    var name = try zarrow.StringBuilder.init(a, rows, rows * 8);
    defer name.deinit();
    for (0..rows) |i| {
        if (i % 7 == 0) try id.appendNull() else try id.append(@intCast(i));
        try value.append(@intCast(i * 3));
        try ok.append((i & 1) == 0);
        try name.append(names[i & 3]);
    }
    var r0 = try id.finish();
    defer r0.release();
    var r1 = try value.finish();
    defer r1.release();
    var r2 = try ok.finish();
    defer r2.release();
    var r3 = try name.finish();
    defer r3.release();
    return zarrow.RecordBatch.init(a, schema_ref.retain(), &[_]zarrow.ArrayRef{ r0, r1, r2, r3 });
}

fn buildBatch2(a: std.mem.Allocator, schema_ref: zarrow.SchemaRef, rows: usize) !zarrow.RecordBatch {
    var ints = try zarrow.Int32Builder.init(a, rows);
    defer ints.deinit();
    var strs = try zarrow.StringBuilder.init(a, rows, rows * 8);
    defer strs.deinit();
    for (0..rows) |i| {
        if (i % 7 == 0) {
            try ints.appendNull();
            try strs.appendNull();
        } else {
            try ints.append(@intCast(i));
            try strs.append(names[i & 3]);
        }
    }
    var r0 = try ints.finish();
    defer r0.release();
    var r1 = try strs.finish();
    defer r1.release();
    return zarrow.RecordBatch.init(a, schema_ref.retain(), &[_]zarrow.ArrayRef{ r0, r1 });
}

fn writeStream(a: std.mem.Allocator, sink: *std.Io.Writer, schema: zarrow.Schema, batch: zarrow.RecordBatch, n: usize, zstd: bool) !void {
    var w = if (zstd) zarrow.IpcStreamWriter.initWithBodyCompression(a, sink, .zstd) else zarrow.IpcStreamWriter.init(a, sink);
    defer w.deinit();
    try w.writeSchema(schema);
    for (0..n) |_| try w.writeRecordBatch(batch);
    try w.writeEnd();
}

fn readStream(a: std.mem.Allocator, bytes: []const u8) !usize {
    var src: std.Io.Reader = .fixed(bytes);
    var r = zarrow.IpcStreamReader.init(a, &src);
    defer r.deinit();
    _ = try r.readSchema();
    var rows: usize = 0;
    while (try r.nextRecordBatch()) |*rb| {
        var b = rb.*;
        defer b.deinit();
        rows += b.numRows();
    }
    return rows;
}

fn readStreamZc(a: std.mem.Allocator, source: zarrow.SharedBuffer) !usize {
    var fixed: std.Io.Reader = .fixed(source.data);
    var r = zarrow.IpcStreamReader.initZeroCopy(a, &fixed, source);
    defer r.deinit();
    _ = try r.readSchema();
    var rows: usize = 0;
    while (try r.nextRecordBatch()) |*rb| {
        var b = rb.*;
        defer b.deinit();
        rows += b.numRows();
    }
    return rows;
}

fn probeRoundtrip(base: std.mem.Allocator, arena_mode: bool, label: []const u8) !void {
    const rows: usize = 20_000;
    const iters: usize = 50;
    const nb: usize = 8;
    const total = rows * iters * nb;
    const fields = [_]zarrow.Field{
        .{ .name = "id", .data_type = &int32_type, .nullable = true },
        .{ .name = "value", .data_type = &int64_type, .nullable = false },
        .{ .name = "ok", .data_type = &bool_type, .nullable = false },
        .{ .name = "name", .data_type = &string_type, .nullable = false },
    };
    const schema = zarrow.Schema{ .fields = fields[0..] };
    var schema_ref = try zarrow.SchemaRef.fromBorrowed(base, schema);
    defer schema_ref.release();
    var batch = try buildBatch4(base, schema_ref, rows);
    defer batch.deinit();

    var arena = std.heap.ArenaAllocator.init(base);
    defer arena.deinit();
    const a = if (arena_mode) arena.allocator() else base;

    if (want("rt_write")) {
        var t_ns: u64 = 0;
        for (0..iters) |_| {
            var sink: std.Io.Writer.Allocating = try .initCapacity(a, rows * nb * 32 + 4096);
            defer sink.deinit();
            const t = now();
            try writeStream(a, &sink.writer, schema, batch, nb, false);
            t_ns += since(t);
            if (arena_mode) _ = arena.reset(.retain_capacity);
        }
        report(try std.fmt.allocPrint(base, "rt_write_{s}", .{label}), t_ns, total);
    }
    if (want("rt_write")) {
