        var sink: std.Io.Writer.Allocating = try .initCapacity(base, rows * nb * 32 + 4096);
        defer sink.deinit();
        @memset(sink.writer.buffer, 0);
        var t_ns: u64 = 0;
        for (0..iters) |_| {
            sink.writer.end = 0;
            const t = now();
            try writeStream(a, &sink.writer, schema, batch, nb, false);
            t_ns += since(t);
            if (arena_mode) _ = arena.reset(.retain_capacity);
        }
        report(try std.fmt.allocPrint(base, "rt_write_warm_sink_{s}", .{label}), t_ns, total);
    }
    var sink: std.Io.Writer.Allocating = try .initCapacity(base, rows * nb * 32 + 4096);
    defer sink.deinit();
    try writeStream(base, &sink.writer, schema, batch, nb, false);
