    if (want("rt_read")) {
        var n: usize = 0;
        const t = now();
        for (0..iters) |_| {
            n += try readStream(a, bytes);
            if (arena_mode) _ = arena.reset(.retain_capacity);
        }
        report(try std.fmt.allocPrint(base, "rt_read_copy_{s}", .{label}), since(t), total);
        std.mem.doNotOptimizeAway(n);
    }
    if (want("rt_read")) {
        var owned = try zarrow.OwnedBuffer.initUninit(base, bytes.len);
        @memcpy(owned.data[0..bytes.len], bytes);
        var source = try owned.toShared(bytes.len);
        defer source.release();
        var n: usize = 0;
        const t = now();
        for (0..iters) |_| {
            n += try readStreamZc(a, source);
            if (arena_mode) _ = arena.reset(.retain_capacity);
        }
        report(try std.fmt.allocPrint(base, "rt_read_zerocopy_{s}", .{label}), since(t), total);
        std.mem.doNotOptimizeAway(n);
    }
    if (want("rt_read")) {
        // floor: one body-sized fresh alloc + memcpy per batch (what the copying read must do)
        const per = bytes.len / nb;
