        .buffers = bufs[0..buf_count],
    };
    try data.validateLayout();
    const t4 = rdtsc();
    prof[3] += t4 - t3;
    const r = try ArrayRef.fromOwnedInlineBuffers(allocator, data);
    prof[4] += rdtsc() - t4;
